package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("ಅಲ್ಲಾಹುಮ್ಮಾ ಬೀಕಾ ಅಸ್ಬಾಹ್ನಾ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾವು ನಿನ್ನ ಮೂಲಕ ಬೆಳಗಿನ ಜಾವ ಪ್ರವೇಶಿಸುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಮೂಲಕ ಸಂಜೆಯನ್ನು ಪ್ರವೇಶಿಸುತ್ತೇವೆ; ನಿನ್ನ ಮೂಲಕ ನಾವು ಬದುಕುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಮೂಲಕ ನಾವು ಸಾಯುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನಲ್ಲಿಯೇ ಪುನರುತ್ಥಾನವಿದೆ.", "ಬೆಳಗಿನ ಜಾವ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಇಂದು ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಹೇಳಲು ಸಹಚರರಿಗೆ ಕಲಿಸಿದರು."),
        "dua_allahumma_bika_amsayna" to DuaText("ಅಲ್ಲಾಹುಮ್ಮಾ ಬೀಕಾ ಅಮ್ಸೇನಾ", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನ ಮೂಲಕ ನಾವು ಸಂಜೆಯನ್ನು ಪ್ರವೇಶಿಸುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಮೂಲಕ ನಾವು ಬೆಳಗಿನ ಸಮಯವನ್ನು ಪ್ರವೇಶಿಸುತ್ತೇವೆ; ನಿನ್ನ ಮೂಲಕ ನಾವು ಬದುಕುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಮೂಲಕ ನಾವು ಸಾಯುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಕಡೆಗೆ ಮರಳುವುದು.", "ಸಂಜೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಇಂದು ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಹೇಳಲು ಸಹಚರರಿಗೆ ಕಲಿಸಿದರು."),
        "dua_afiyah_morning" to DuaText("ಅಫಿಯಾ ಕೇಳುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ಈ ಲೋಕದಲ್ಲಿ ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ಕ್ಷಮೆ ಮತ್ತು ಕ್ಷೇಮಕ್ಕಾಗಿ ನಾನು ನಿನ್ನನ್ನು ಕೋರುತ್ತೇನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ದಿನವನ್ನು ಬೆಳಿಗ್ಗೆ ಅಥವಾ ಸಂಜೆ ಎಂದಿಗೂ ಬಿಡಲಿಲ್ಲ.", "ಯೋಗಕ್ಷೇಮಕ್ಕಿಂತ ಉತ್ತಮವಾದದ್ದನ್ನು ಯಾರಿಗೂ ನೀಡಲಾಗಿಲ್ಲ."),
        "dua_afini_fi_badani" to DuaText("ದೇಹ, ಶ್ರವಣ ಮತ್ತು ದೃಷ್ಟಿ ಆರೋಗ್ಯ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ದೇಹಕ್ಕೆ ಕ್ಷೇಮವನ್ನು ಕರುಣಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಶ್ರವಣಕ್ಕೆ ಕ್ಷೇಮವನ್ನು ಕರುಣಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ದೃಷ್ಟಿಗೆ ಕ್ಷೇಮವನ್ನು ಕರುಣಿಸು. ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ.", "ಪ್ರತಿ ದಿನ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಮೂರು ಬಾರಿ.", "ಆರೋಗ್ಯ ಮತ್ತು ಇಂದ್ರಿಯಗಳ ರಕ್ಷಣೆಗಾಗಿ ಒಂದು ದುಆ."),
        "dua_ya_hayyu_aslih" to DuaText("ನನ್ನ ಎಲ್ಲಾ ವ್ಯವಹಾರಗಳನ್ನು ಸರಿಪಡಿಸಿ", "ಓ ನಿತ್ಯಜೀವಿಯಾದ ಓ ಪಾಲಕನೇ, ನಿನ್ನ ಕರುಣೆಯಿಂದ ನಾನು ಸಹಾಯವನ್ನು ಕೋರುತ್ತೇನೆಃ ನನ್ನ ಎಲ್ಲಾ ವ್ಯವಹಾರಗಳನ್ನು ಸರಿಪಡಿಸಿ ಮತ್ತು ಒಂದು ಕಣ್ಣು ಮಿಟುಕಿಸುವವರೆಗೂ ನನ್ನನ್ನು ನನ್ನ ಮೇಲೆ ಬಿಡಬೇಡಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರು ಇದನ್ನು ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಹೇಳುವಂತೆ ಫಾತಿಮಾ (ರ) ಅವರಿಗೆ ಸಲಹೆ ನೀಡಿದರು.", "ಪ್ರತಿಯೊಂದು ವಿಷಯದಲ್ಲೂ ಅಲ್ಲಾಹನಿಂದ ಸಹಾಯವನ್ನು ಕೋರುತ್ತಾರೆ."),
        "dua_subhanallah_adada_khalqihi" to DuaText("ಜುವೇರಿಯಾಹ್ ನ ತಸ್ಬೆಹ್ (ಆರ್. ಎ.)", "ಅಲ್ಲಾಹನಿಗೆ ಮಹಿಮೆ ಇರಲಿ ಮತ್ತು ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅವನದೇ-ಅವನ ಸೃಷ್ಟಿಗೆ ಎಷ್ಟು ಇಷ್ಟವೋ ಅಷ್ಟು, ಅವನ ಸಿಂಹಾಸನದ ತೂಕ ಮತ್ತು ಅವನ ಮಾತುಗಳ ಶಾಯಿಯಷ್ಟೇ.", "ಬೆಳಿಗ್ಗೆ ಮೂರು ಬಾರಿ-ಗಂಟೆಗಟ್ಟಲೆ ಧಿಕ್ರ್ ಗಿಂತ ಹೆಚ್ಚು ಭಾರವಾಗಿರುತ್ತದೆ.", "ಈ ನಾಲ್ಕು ನುಡಿಗಟ್ಟುಗಳನ್ನು ಮೂರು ಬಾರಿ ಹೇಳುವುದು ಬೆಳಗಿನಿಂದ ಮಧ್ಯ ಬೆಳಗಿನವರೆಗೆ ಧಿಕ್ರಕ್ಕಿಂತ ಹೆಚ್ಚು."),
        "dua_salawat" to DuaText("ದುರೂದ್-ಎ-ಇಬ್ರಾಹಿಮಿ", "ಓ ಅಲ್ಲಾಹ್ವೇ, ನೀವು ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಮತ್ತು ಇಬ್ರಾಹಿಂನ ಕುಟುಂಬದವರ ಮೇಲೆ ಪ್ರಾರ್ಥನೆಗಳನ್ನು ಕಳುಹಿಸಿದಂತೆ ಮುಹಮ್ಮದ್ (ಸ) ಮತ್ತು ಮುಹಮ್ಮದ್ (ಸ) ಅವರ ಕುಟುಂಬದ ಮೇಲೆ ಪ್ರಾರ್ಥನೆಗಳನ್ನು ಕಳುಹಿಸಿ. ನೀವು ಶ್ಲಾಘನೀಯರು, ಮಹಿಮಾವಂತರು. ಓ ಅಲ್ಲಾಹ್ವೇ, ನೀವು ಮುಹಮ್ಮದ್ (ಸ) ಮತ್ತು ಮುಹಮ್ಮದ್ (ಸ) ಅವರ ಕುಟುಂಬವನ್ನು ಆಶೀರ್ವದಿಸಿದಂತೆ ಮುಹಮ್ಮದ್ (ಸ) ಮತ್ತು ಇಬ್ರಾಹಿಂ (ಸ) ಅವರ ಕುಟುಂಬವನ್ನು ಆಶೀರ್ವದಿಸಿ; ನೀವು ಶ್ಲಾಘನೀಯರು, ಮಹಿಮಾವಂತರು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ ಮತ್ತು ಎಲ್ಲಾ ಸಮಯದಲ್ಲೂ ಸಲಾವತ್.", "ಯಾರು ಒಂದು ಬಾರಿ ಸಲಾವತ್ ಕಳುಹಿಸುತ್ತಾರೋ, ಅಲ್ಲಾಹ್ ಅವನ ಮೇಲೆ ಹತ್ತು ಕರುಣೆಗಳನ್ನು ಕಳುಹಿಸುತ್ತಾನೆ (ಮುಸ್ಲಿಂ 408)."),
        "dua_wudu_after" to DuaText("ವುಡು ನಂತರ", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದೆ, ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ ಮತ್ತು ಮುಹಮ್ಮದ್ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಆತನ ಸೇವಕ ಮತ್ತು ಸಂದೇಶವಾಹಕರಾಗಿದ್ದಾರೆ ಎಂಬುದಕ್ಕೆ ನಾನು ಸಾಕ್ಷಿಯಾಗಿದ್ದೇನೆ. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ಪಶ್ಚಾತ್ತಾಪಪಡುವವರ ಮತ್ತು ತಮ್ಮನ್ನು ತಾವು ಶುದ್ಧೀಕರಿಸಿಕೊಳ್ಳುವವರಲ್ಲನ್ನಾಗಿ ಮಾಡು.", "ವೂಡು ಪೂರ್ಣಗೊಳಿಸಿದ ನಂತರ.", "ಸ್ವರ್ಗದ ಎಂಟು ಬಾಗಿಲುಗಳನ್ನು ಆತನು ತನಗೆ ಬೇಕಾದ ರೀತಿಯಲ್ಲಿ ಪ್ರವೇಶಿಸಲು ತೆರೆಯಲಾಗುತ್ತದೆ."),
        "dua_wudu_before" to DuaText("ವುಡು ಮೊದಲು", "ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ.", "ವೂಡು ಪ್ರಾರಂಭಿಸುವಾಗ.", "ಅಲ್ಲಾಹನ ಹೆಸರನ್ನು ಅದರ ಮೇಲೆ ಉಲ್ಲೇಖಿಸದವರಿಗೆ ಯಾವುದೇ (ಸಂಪೂರ್ಣ) ವುಡು ಇಲ್ಲ."),
        "dua_istiftah" to DuaText("ಆರಂಭಿಕ ಪ್ರಾರ್ಥನೆ (ಸನಾ)", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನಗೆ ಮಹಿಮೆ ಇರಲಿ ಮತ್ತು ನಿನಗೆ ಸ್ತೋತ್ರವಾಗಲಿ. ನಿನ್ನ ಹೆಸರು ಧನ್ಯವಾಗಿದೆ, ನಿನ್ನ ಮಹಿಮೆ ಉದಾತ್ತವಾಗಿದೆ, ಮತ್ತು ನಿನ್ನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ದೇವರು ಇಲ್ಲ.", "ಪ್ರಾರ್ಥನೆಯ ಪ್ರಾರಂಭದಲ್ಲಿ, ಉದ್ಘಾಟನಾ ತಕ್ಬೀರ್ ನಂತರ.", "ಪ್ರಾರ್ಥನೆಯ ಸುನ್ನಾ ಆರಂಭಿಕ ದುಆ."),
        "dua_ruku" to DuaText("ರುಕುನಲ್ಲಿ", "ಮಹಿಮೆ ನನ್ನ ಒಡೆಯನಿಗೆ, ಮಹಿಮೆ.", "ರುಕುನಲ್ಲಿ ಕನಿಷ್ಠ ಮೂರು ಬಾರಿ.", "ರುಕುವಿನ ಸುನ್ನಹ್ ತಸ್ಬಿಹ್."),
        "dua_sujood" to DuaText("ಸುಜೂದ್ನಲ್ಲಿ", "ಮಹೋನ್ನತನಾದ ನನ್ನ ಒಡೆಯನಿಗೆ ಮಹಿಮೆ ಇರಲಿ.", "ಕನಿಷ್ಠ ಮೂರು ಬಾರಿ ಸುಜೂದ್ನಲ್ಲಿ.", "ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡುವಾಗ ಸೇವಕನು ತನ್ನ ಪ್ರಭುವಿಗೆ ಅತ್ಯಂತ ಹತ್ತಿರವಾಗಿರುತ್ತಾನೆ (ಮುಸ್ಲಿಂ 482)."),
        "dua_rising_ruku" to DuaText("ರುಕುವಿನಿಂದ ಉದಯ", "ತನ್ನನ್ನು ಸ್ತುತಿಸುವವನ ಮಾತನ್ನು ಅಲ್ಲಾಹು ಕೇಳುತ್ತಾನೆ. ನಮ್ಮ ಒಡೆಯನೇ, ಎಲ್ಲ ಸ್ತುತಿಯೂ ನಿನಗೇ ಸೇರಿದ್ದು.", "ರುಕುವಿನಿಂದ ಎದ್ದು ನೇರವಾಗಿ ನಿಂತಾಗ.", "ಯಾರೊಬ್ಬರ'ರಬ್ಬಾನಾ ವಾ ಲಕಲ್-ಹಮ್ದ್'ದೇವತೆಗಳ ಪಾಪಗಳೊಂದಿಗೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆಯೋ, ಅವರ ಹಿಂದಿನ ಪಾಪಗಳು ಕ್ಷಮಿಸಲ್ಪಡುತ್ತವೆ."),
        "dua_between_sajdas" to DuaText("ಇಬ್ಬರು ಸಜ್ಜ್ದಾಸ್ ನಡುವೆ", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು. ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ಎರಡು ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರಗಳ ನಡುವೆ ಕುಳಿತುಕೊಳ್ಳುವಾಗ.", "ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರದ ನಡುವೆ ಕುಳಿತುಕೊಳ್ಳುವ ಸುನ್ನತ್ ದುಆ."),
        "dua_before_salam_four" to DuaText("ನಾಲ್ಕು ವಿಷಯಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ (ಸಲಾಂ ಮೊದಲು)", "ಓ ಅಲ್ಲಾಹನೇ, ನರಕದ ಶಿಕ್ಷೆಯಿಂದ, ಸಮಾಧಿಯ ಶಿಕ್ಷೆಯಿಂದ, ಜೀವನ ಮತ್ತು ಮರಣದ ಪರೀಕ್ಷೆಗಳಿಂದ ಮತ್ತು ಸುಳ್ಳು ಮೆಸ್ಸಿಹ್ನ (ದಜ್ಜಲ್) ವಿಚಾರಣೆಯ ದುಷ್ಟತನದಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಅಂತಿಮ ತಾಶಹುದ್ ಮತ್ತು ಸಲಾವತ್ ನಂತರ, ಸಲಾಂ ಮೊದಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ನಾಲ್ಕು ವಿಷಯಗಳಿಂದ ಆಶ್ರಯ ಪಡೆಯಲು ಆದೇಶಿಸಿದರು."),
        "dua_qunoot_witr" to DuaText("ವಿತರ್ನಲ್ಲಿ ಕುನೂಟ್", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಮಾರ್ಗದರ್ಶಿಗಳಾಗಿರುವವರಲ್ಲಿ ನನಗೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡು. ನೀನು ಕಲ್ಯಾಣವನ್ನು ನೀಡಿದವರಲ್ಲಿ ನನಗೆ ಕಲ್ಯಾಣವನ್ನು ಮಾಡು. ನೀನು ನಿಮ್ಮ ಆರೈಕೆಗಾಗಿ ತೆಗೆದುಕೊಂಡವರಲ್ಲಿ ನನ್ನನ್ನು ನಿಮ್ಮ ಆರೈಕೆಗೆ ತೆಗೆದುಕೊಳ್ಳಿ. ನೀನು ಕೊಟ್ಟದ್ದರಲ್ಲಿ ನನ್ನನ್ನು ಆಶೀರ್ವದಿಸು. ಮತ್ತು ನೀನು ವಿಧಿಸಿದ ಕೆಟ್ಟತನದಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸು. ನೀನು ಆದೇಶಿಸು, ಮತ್ತು ನಿನ್ನ ವಿರುದ್ಧ ಯಾವುದೇ ತೀರ್ಪು ನೀಡುವುದಿಲ್ಲ, ಮತ್ತು ನೀನು ಸ್ನೇಹ ಬೆಳೆಸುವವನು ಎಂದಿಗೂ ಅವಮಾನಕ್ಕೆ ಒಳಗಾಗುವುದಿಲ್ಲ. ನಮ್ಮ ಒಡೆಯನೇ, ನೀನು ಧನ್ಯ ಮತ್ತು ಉದಾತ್ತ.", "ವಿತ್ರ್ ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಇದನ್ನು ಹಸನ್ ಇಬ್ನ್ ಅಲಿ (ರ. ಅ.) ಗೆ ಕಲಿಸಿದರು.", "ವಿದ್ರ್ನ ಸುನ್ನಹ್ ಕುನೂತ್. (ಹನಾಫಿಗಳಲ್ಲಿ,'ಅಲ್ಲಾಹುಮ್ಮಾ ಇನ್ನಾ ನಾಸ್ತಾನುಕಾ'ಕೂಡ ಪ್ರಸಿದ್ಧವಾಗಿದೆ.)"),
        "dua_qunoot_hanafi" to DuaText("ಕುನೂತ್ (ಅಲ್ಲಾಹುಮ್ಮಾ ಇನ್ನಾ ನಾಸ್ತೈನುಕಾ)", "ಓ ಅಲ್ಲಾಹನೇ, ನಾವು ನಿನ್ನ ಸಹಾಯ ಮತ್ತು ನಿನ್ನ ಕ್ಷಮೆಯನ್ನು ಕೋರುತ್ತೇವೆ, ನಾವು ನಿನ್ನನ್ನು ನಂಬುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನನ್ನು ಅವಲಂಬಿಸುತ್ತೇವೆ, ನಾವು ನಿನ್ನನ್ನು ಅತ್ಯುತ್ತಮ ರೀತಿಯಲ್ಲಿ ಸ್ತುತಿಸುತ್ತೇವೆ, ನಾವು ನಿನಗೆ ಕೃತಜ್ಞತೆ ಸಲ್ಲಿಸುತ್ತೇವೆ ಮತ್ತು ಕೃತಘ್ನರಾಗುವುದಿಲ್ಲ, ಮತ್ತು ನಿನಗೆ ಅವಿಧೇಯನಾಗುವವರನ್ನು ನಾವು ತ್ಯಜಿಸುತ್ತೇವೆ. ಓ ಅಲ್ಲಾಹನೇ, ನಾವು ನಿನ್ನನ್ನು ಮಾತ್ರ ಆರಾಧಿಸುತ್ತೇವೆ ಮತ್ತು ನಮಸ್ಕರಿಸುತ್ತೇವೆ, ನಾವು ನಿನ್ನನ್ನು ಪ್ರಾರ್ಥಿಸುತ್ತೇವೆ ಮತ್ತು ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡುತ್ತೇವೆ, ನಾವು ನಿನ್ನ ಕಡೆಗೆ ಧಾವಿಸುತ್ತೇವೆ ಮತ್ತು ಪ್ರಯತ್ನಿಸುತ್ತೇವೆ, ನಾವು ನಿನ್ನ ಕರುಣೆಯನ್ನು ನಿರೀಕ್ಷಿಸುತ್ತೇವೆ ಮತ್ತು ನಿನ್ನ ಶಿಕ್ಷೆಗೆ ಭಯಪಡುತ್ತೇವೆ; ಖಂಡಿತವಾಗಿಯೂ ನಿನ್ನ ಶಿಕ್ಷೆಯು ನಿರಾಕರಿಸುವವರನ್ನು ತಲುಪುತ್ತದೆ.", "ವಿಟರ್-ಹನಾಫಿಗಳ ಅಭ್ಯಾಸ.", "ಕುನೂತ್ನಲ್ಲಿ ಉಮರ್ (ರ.) ಅವರಿಂದ ವರದಿಯಾಗಿದೆ."),
        "dua_sleep_aslamtu" to DuaText("ಮಲಗುವ ಮೊದಲು ಕೊನೆಯ ಮಾತುಗಳು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುತ್ತೇನೆ. ನನ್ನ ವ್ಯವಹಾರವನ್ನು ನಿನಗೆ ಒಪ್ಪಿಸುತ್ತೇನೆ. ನಿನ್ನಲ್ಲಿ ಭರವಸೆ ಮತ್ತು ನಿನ್ನ ಭಯದಿಂದ ನನ್ನ ರಕ್ಷಣೆಗೆ ನನ್ನ ಬೆನ್ನನ್ನು ಒಪ್ಪಿಸುತ್ತೇನೆ. ನಿನ್ನ ಹೊರತು ನಿನಗೆ ಆಶ್ರಯವಿಲ್ಲ ಮತ್ತು ನಿನ್ನಿಂದ ತಪ್ಪಿಸಿಕೊಳ್ಳುವದಿಲ್ಲ. ನೀನು ಪ್ರಕಟಿಸಿದ ನಿನ್ನ ಗ್ರಂಥವನ್ನು ಮತ್ತು ನೀನು ಕಳುಹಿಸಿದ ನಿನ್ನ ಪ್ರವಾದಿಯನ್ನು ನಾನು ನಂಬುತ್ತೇನೆ.", "ವೂಡು ನಂತರ, ಬಲಭಾಗದಲ್ಲಿ ಮಲಗುವುದು-ಮಲಗುವ ಮೊದಲು ಕೊನೆಯ ಪದಗಳು.", "ಆ ರಾತ್ರಿ ಅವನು ಸತ್ತರೆ, ಅವನು ಫಿತ್ರಾದಲ್ಲಿ (ಇಸ್ಲಾಂ) ಸಾಯುತ್ತಾನೆ."),
        "dua_waking_night" to DuaText("ರಾತ್ರಿಯಲ್ಲಿ ಎಚ್ಚರಗೊಳ್ಳುವುದು", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ, ಒಬ್ಬನೇ, ಪಾಲುದಾರನಿಲ್ಲದ, ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಪ್ರಭುತ್ವವು ಅವನಿಗೇ ಇದೆ ಮತ್ತು ಸ್ತುತಿಯೂ ಅವನಿಗೇ ಇದೆ, ಮತ್ತು ಅವನು ಎಲ್ಲ ವಿಷಯಗಳ ಮೇಲೆ ಅಧಿಕಾರವನ್ನು ಹೊಂದಿದ್ದಾನೆ. ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅಲ್ಲಾಹನಿಗೇ ಇದೆ, ಮಹಿಮೆಯೂ ಅಲ್ಲಾಹನಿಗೇ ಇದೆ, ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಆರಾಧಿಸಲ್ಪಡುವ ಹಕ್ಕು ಯಾರಿಗೂ ಇಲ್ಲ. ಅಲ್ಲಾಹನೇ ದೊಡ್ಡವನು, ಮತ್ತು ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಯಾವುದೇ ಶಕ್ತಿ ಅಥವಾ ಶಕ್ತಿ ಇಲ್ಲ. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ರಾತ್ರಿಯಲ್ಲಿ ಎಚ್ಚರವಾದಾಗ.", "ಅವನ ದುಆಕ್ಕೆ ಉತ್ತರಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು ಅವನು ವುಡು ಮಾಡಿ ಪ್ರಾರ್ಥಿಸಿದರೆ, ಅವನ ಪ್ರಾರ್ಥನೆಯನ್ನು ಸ್ವೀಕರಿಸಲಾಗುತ್ತದೆ."),
        "dua_hamm_ibn_masud" to DuaText("ದುಃಖಕ್ಕಾಗಿ ದುಆ (ಇಬ್ನ್ ಮಸೂದ್)", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನ ಸೇವಕನೇ, ನಿನ್ನ ಸೇವಕನ ಮಗನೇ, ನಿನ್ನ ದಾಸಿಯ ಮಗನೇ, ನಿನ್ನ ದಾಸಿಯ ಮಗನೇ. ನನ್ನ ಮುಂಭಾಗವು ನಿನ್ನ ಕೈಯಲ್ಲಿದೆ, ನನ್ನ ಮೇಲೆ ನಿನ್ನ ಆಜ್ಞೆಯು ನೆರವೇರುತ್ತದೆ, ಮತ್ತು ನನ್ನ ಬಗ್ಗೆ ನಿನ್ನ ಆಜ್ಞೆಯು ನ್ಯಾಯಯುತವಾಗಿದೆ. ನಾನು ನಿನ್ನನ್ನು ಕೇಳುವ ಪ್ರತಿಯೊಂದು ಹೆಸರಿನಿಂದಲೂ, ನೀವು ನಿಮ್ಮನ್ನು ಹೆಸರಿಸಿಕೊಂಡಿದ್ದೀರಿ, ಅಥವಾ ನಿಮ್ಮ ಪುಸ್ತಕದಲ್ಲಿ ಪ್ರಕಟಿಸಿದ್ದೀರಿ, ಅಥವಾ ನಿಮ್ಮ ಯಾವುದೇ ಸೃಷ್ಟಿಗೆ ಕಲಿಸಿದ್ದೀರಿ, ಅಥವಾ ಅದೃಶ್ಯ ಜ್ಞಾನದಲ್ಲಿ ನಿನ್ನೊಂದಿಗೆ ಇಟ್ಟುಕೊಂಡಿದ್ದೀರಿ-ನೀವು ಕುರಾನನ್ನು ನನ್ನ ಹೃದಯದ ಬುಗ್ಗೆಯನ್ನಾಗಿ ಮಾಡಿದ್ದೀರಿ, ನನ್ನ ಎದೆಯ ಬೆಳಕನ್ನು ಮಾಡಿದ್ದೀರಿ, ನನ್ನ ದುಃಖವನ್ನು ತೆಗೆದುಹಾಕುತ್ತೀರಿ ಮತ್ತು ನನ್ನ ಚಿಂತೆಗಳನ್ನು ಬಿಟ್ಟುಬಿಟ್ಟಿದ್ದೀರಿ.", "ದುಃಖ ಮತ್ತು ಯಾತನೆಯಲ್ಲಿ-ಅಲ್ಲಾಹು ದುಃಖವನ್ನು ಸಂತೋಷದಿಂದ ಬದಲಾಯಿಸುತ್ತಾನೆ.", "ಅಲ್ಲಾಹು ಅವನ ಚಿಂತೆ ಮತ್ತು ದುಃಖವನ್ನು ತೆಗೆದುಹಾಕುತ್ತಾನೆ ಮತ್ತು ಅದರ ಸ್ಥಳದಲ್ಲಿ ಸಂತೋಷವನ್ನು ನೀಡುತ್ತಾನೆ."),
        "dua_difficulty_sahl" to DuaText("ಏನಾದರೂ ಕಷ್ಟವಾದಾಗ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಸುಲಭಗೊಳಿಸುವುದನ್ನೇ ಹೊರತು ಬೇರೆ ಯಾವುದೂ ಸುಲಭವಲ್ಲ, ಮತ್ತು ನೀನು ಬಯಸಿದರೆ ಕಷ್ಟವನ್ನು ಸುಲಭಗೊಳಿಸು.", "ಏನಾದರೂ ಕಷ್ಟವೆನಿಸುವಾಗ.", "ಪರೀಕ್ಷೆಗಳಲ್ಲಿ ಸುಲಭತೆ ಮತ್ತು ಕಷ್ಟಕರ ಕಾರ್ಯಗಳು."),
        "dua_musibah" to DuaText("ಅಪಾನ್ ಎ ಕ್ಯಾಲಮಿಟಿ (ಇಸ್ತಿರ್ಜಾ)", "ನಾವು ಅಲ್ಲಾಹನಿಗೆ ಸೇರಿದವರಾಗಿದ್ದೇವೆ ಮತ್ತು ಅವನ ಕಡೆಗೆ ಹಿಂದಿರುಗುತ್ತೇವೆ. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಯಾತನೆಯಲ್ಲಿ ನನಗೆ ಪ್ರತಿಫಲ ಕೊಡು ಮತ್ತು ಅದರ ಬದಲಿಗೆ ನನಗೆ ಉತ್ತಮವಾದದ್ದನ್ನು ಕೊಡು.", "ಯಾವುದೇ ನಷ್ಟ ಅಥವಾ ವಿಪತ್ತಿನ ಮೇಲೆ.", "ಅಲ್ಲಾಹ್ ಖಂಡಿತವಾಗಿಯೂ ಇದಕ್ಕಿಂತ ಉತ್ತಮವಾದದ್ದನ್ನು ನೀಡುತ್ತಾನೆ-ಉಮ್ ಸಲಮಾ (ರ) ಅವರಿಗೆ ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ (ಸ) ಅವರನ್ನು ನೀಡಲಾಯಿತು."),
        "dua_debt" to DuaText("ಸಾಲದಿಂದ ಮುಕ್ತಿಗಾಗಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ನಿಷಿದ್ಧಗೊಳಿಸಿದ್ದಕ್ಕೆ ವಿರುದ್ಧವಾಗಿ ನೀನು ಕಾನೂನುಬದ್ಧಗೊಳಿಸಿದ್ದನ್ನು ನನಗೆ ನೀಡಿ, ಮತ್ತು ನಿನ್ನ ಅನುಗ್ರಹದಿಂದ ನನ್ನನ್ನು ನಿನ್ನನ್ನು ಹೊರತುಪಡಿಸಿ ಎಲ್ಲರಿಂದಲೂ ಸ್ವತಂತ್ರಗೊಳಿಸು.", "ಸಾಲವನ್ನು ತೀರಿಸಲು-ಅಲಿ (ಆರ್. ಎ.) ಕಲಿಸಿದ.", "ಸಾಲವು ಪರ್ವತದಂತೆ ಇದ್ದರೂ, ಅಲ್ಲಾಹ್ ಅದನ್ನು ತೀರಿಸುತ್ತಾನೆ."),
        "dua_anger" to DuaText("ಕೋಪಗೊಂಡಾಗ", "ನಾನು ಶಾಪಗ್ರಸ್ತರಾದ ಸೈತಾನ್ನಿಂದ ಅಲ್ಲಾಹನ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಕೋಪಗೊಂಡಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಹೇಳಿದರುಃ ಅವರು ಇದನ್ನು ಹೇಳಿದರೆ, ಅವರ ಕೋಪವು ಹೋಗುತ್ತದೆ."),
        "dua_waswasa" to DuaText("ನಂಬಿಕೆಯಲ್ಲಿ ವಾಸವಾಸರ ವಿರುದ್ಧ", "ನಾನು ಅಲ್ಲಾಹ್ ಮತ್ತು ಆತನ ದೂತರನ್ನು ನಂಬುತ್ತೇನೆ.", "ನಂಬಿಕೆಯ ಬಗ್ಗೆ ಸೈತಾನನ ಪಿಸುಗುಟ್ಟುವುದು ಬಂದಾಗ ಬರುತ್ತದೆ.", "ಪಿಸುಗುಟ್ಟುವುದು ಬಂದಾಗ, ಇದನ್ನು ಹೇಳಿ ಮತ್ತು ಅಲ್ಲಿಯೇ ನಿಲ್ಲಿ (ಮತ್ತು ಅಲ್ಲಾಹನ ಆಶ್ರಯವನ್ನೂ ಪಡೆಯಿರಿ)."),
        "dua_travel_full" to DuaText("ಸಂಪೂರ್ಣ ಪ್ರಯಾಣದ ಪ್ರಾರ್ಥನೆ", "ಓ ಅಲ್ಲಾಹನೇ, ಈ ಪ್ರಯಾಣದಲ್ಲಿ ನಾವು ನಿನ್ನನ್ನು ಸದಾಚಾರ ಮತ್ತು ಧರ್ಮನಿಷ್ಠೆಗಾಗಿ ಮತ್ತು ನಿನಗೆ ಇಷ್ಟವಾದ ಕಾರ್ಯಗಳಿಗಾಗಿ ಕೋರುತ್ತೇವೆ. ಓ ಅಲ್ಲಾಹನೇ, ಈ ಪ್ರಯಾಣವನ್ನು ನಮಗೆ ಸುಲಭಗೊಳಿಸು ಮತ್ತು ಅದರ ದೂರವನ್ನು ಕಡಿಮೆ ಮಾಡು. ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಪ್ರಯಾಣದಲ್ಲಿ ಸಹಚರನಾಗಿದ್ದೀ ಮತ್ತು ಕುಟುಂಬದ ರಕ್ಷಕನಾಗಿದ್ದೀ.", "ಪ್ರಯಾಣಕ್ಕೆ ಹೊರಟಾಗ,'ಸುಭಾನಲ್ಲಧಿ ಸಖಾರಾ'ದ ನಂತರ.", "ಸಂಪೂರ್ಣ ಸುನ್ನತವು ಪ್ರಯಾಣದ ದುಆ."),
        "dua_return_travel" to DuaText("ಪ್ರಯಾಣದಿಂದ ಹಿಂತಿರುಗಿ", "ನಾವು ಹಿಂತಿರುಗುತ್ತೇವೆ, ಪಶ್ಚಾತ್ತಾಪಪಡುತ್ತೇವೆ, ನಮ್ಮ ಭಗವಂತನನ್ನು ಪೂಜಿಸುತ್ತೇವೆ ಮತ್ತು ಸ್ತುತಿಸುತ್ತೇವೆ.", "ಪ್ರಯಾಣದಿಂದ ಹಿಂದಿರುಗಿದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರಯಾಣದಿಂದ ಹಿಂದಿರುಗಿದಾಗ ಈ ಮಾತನ್ನು ಹೇಳಿದರು."),
        "dua_farewell_traveller" to DuaText("ಪ್ರಯಾಣಿಕರಿಗೆ ವಿದಾಯ ಹೇಳುವುದು", "ನಾನು ನಿಮ್ಮ ಧರ್ಮ, ನಿಮ್ಮ ನಂಬಿಕೆ ಮತ್ತು ನಿಮ್ಮ ಕರ್ಮಗಳ ಫಲವನ್ನು ಅಲ್ಲಾಹನಿಗೆ ಒಪ್ಪಿಸುತ್ತೇನೆ.", "ಒಬ್ಬ ಪ್ರಯಾಣಿಕನಿಗೆ ವಿದಾಯ ಹೇಳುವಾಗ.", "ಅಲ್ಲಾಹನಿಗೆ ವಹಿಸಿಕೊಟ್ಟದ್ದನ್ನು ಎಂದಿಗೂ ಕಳೆದುಕೊಳ್ಳುವುದಿಲ್ಲ."),
        "dua_entering_town" to DuaText("ಒಂದು ಸ್ಥಳದಲ್ಲಿ ನಿಲ್ಲುವುದು", "ನಾನು ಅಲ್ಲಾಹನ ಪರಿಪೂರ್ಣ ಮಾತುಗಳಲ್ಲಿ ಆತನು ಸೃಷ್ಟಿಸಿದ ಎಲ್ಲದರ ದುಷ್ಟತನದಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಒಂದು ಸ್ಥಳದಲ್ಲಿ ನಿಲ್ಲುವಾಗ ಅಥವಾ ಹೊಸ ಪಟ್ಟಣಕ್ಕೆ ಆಗಮಿಸುವಾಗ.", "ಅವನು ಅಲ್ಲಿಂದ ಹೊರಡುವವರೆಗೂ ಅವನಿಗೆ ಏನೂ ಹಾನಿಯಾಗುವುದಿಲ್ಲ."),
        "dua_boarding_ship" to DuaText("ಹಡಗು/ವಾಹನವನ್ನು ಹತ್ತುವುದು", "ಅದರ ನೌಕಾಯಾನ ಮತ್ತು ಅದರ ಲಂಗರು ಅಲ್ಲಾಹನ ಹೆಸರಿನಲ್ಲಿ ಇದೆ. ಖಂಡಿತವಾಗಿಯೂ ನನ್ನ ಒಡೆಯನು ಕ್ಷಮಾಶೀಲನೂ ಕರುಣಾಮಯನೂ ಆಗಿದ್ದಾನೆ.", "ಹಡಗು ಅಥವಾ ವಾಹನವನ್ನು ಹತ್ತುವಾಗ-ಪ್ರವಾದಿ ನೂಹ್ (ಅ. ಸ.) ಅವರ ಮಾತುಗಳು.", "ಕುರಾನ್ ಪದ್ಯ-ನೂಹ್ (ಎ. ಎಸ್) ಆರ್ಕ್ನ ದುಆ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("ಹಯುಲ್-ಕಯುಮ್ ಜೊತೆ ಇಸ್ತಿಘಫರ್", "ನಾನು ಅಲ್ಲಾಹನಿಂದ ಕ್ಷಮೆ ಕೋರುತ್ತೇನೆ, ಅವನನ್ನು ಹೊರತುಪಡಿಸಿ ಯಾವುದೇ ದೇವರು, ಶಾಶ್ವತ, ಪೋಷಕರಿಲ್ಲ, ಮತ್ತು ನಾನು ಪಶ್ಚಾತ್ತಾಪದಿಂದ ಅವನ ಕಡೆಗೆ ತಿರುಗುತ್ತೇನೆ.", "ಪಶ್ಚಾತ್ತಾಪಕ್ಕಾಗಿ.", "ಅವನು ಯುದ್ಧಭೂಮಿಯಿಂದ ಓಡಿಹೋದರೂ ಅವನ ಪಾಪಗಳು ಕ್ಷಮಿಸಲ್ಪಡುತ್ತವೆ."),
        "dua_rabbighfir_warham" to DuaText("ರಾಬಿಗ್ಫಿರ್ ವಾರ್ಹಾಮ್", "ನನ್ನ ಒಡೆಯನೇ, ನೀನು ಕ್ಷಮಿಸು ಮತ್ತು ಕರುಣಿಸು, ಯಾಕಂದರೆ ನೀನು ಕರುಣಿಸುವವರಲ್ಲಿ ಅತ್ಯುತ್ತಮನಾಗಿದ್ದೀ.", "ಕುರಾನ್ ದುಆ-ಕ್ಷಮೆಯಾಚಿಸಲು ಮತ್ತು ಕರುಣೆಗಾಗಿ.", "ಸೂರಹ್ ಅಲ್-ಮು'ಮಿನುನ್ನ ಕೊನೆಯ ಪದ್ಯ."),
        "dua_majlis_kaffarah" to DuaText("ಕಫರತ್ ಅಲ್-ಮಜ್ಲಿಸ್", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನಗೆ ಮಹಿಮೆ ಮತ್ತು ಸ್ತುತಿಯೂ ಇರಲಿ. ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ ಎಂದು ನಾನು ಸಾಕ್ಷಿಯಾಗಿ ಹೇಳುತ್ತೇನೆ. ನಾನು ನಿನ್ನನ್ನು ಕ್ಷಮಿಸಿ ಪಶ್ಚಾತ್ತಾಪ ಪಡುತ್ತೇನೆ.", "ಸಭೆಯಿಂದ ಎದ್ದಾಗ.", "ಸಭೆಯಲ್ಲಿ ಹೇಳಲಾದ ಯಾವುದೇ ತಪ್ಪಿನ ಪ್ರಾಯಶ್ಚಿತ್ತವಾಗಿ ಇದು ಪರಿಣಮಿಸುತ್ತದೆ."),
        "dua_jami_forgiveness" to DuaText("ಸಮಗ್ರ ಕ್ಷಮೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ತಪ್ಪುಗಳನ್ನು, ನನ್ನ ಅಜ್ಞಾನವನ್ನು, ನನ್ನ ವ್ಯವಹಾರಗಳಲ್ಲಿ ನನ್ನ ಮಿತಿಮೀರಿದ ಕಾರ್ಯಗಳನ್ನು ಮತ್ತು ನನಗಿಂತ ಚೆನ್ನಾಗಿ ನಿನಗೆ ತಿಳಿದಿರುವ ಎಲ್ಲವನ್ನೂ ನನಗೆ ಕ್ಷಮಿಸು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಸಮಗ್ರ ದುಆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಈ ದುಆವನ್ನು ತಯಾರಿಸುತ್ತಿದ್ದರು."),
        "dua_parents_nuh" to DuaText("ಪೋಷಕರಿಗೆ ನೂಹ್ (ಎ. ಎಸ್) ನ ದುವಾ", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನ ತಂದೆ-ತಾಯಿಗಳೇ, ನನ್ನ ಮನೆಗೆ ವಿಶ್ವಾಸಿಯಾಗಿ ಪ್ರವೇಶಿಸುವವರನ್ನೆಲ್ಲ ಮತ್ತು ನಂಬಿಕೆಯುಳ್ಳ ಪುರುಷರು ಮತ್ತು ಮಹಿಳೆಯರೆಲ್ಲರನ್ನೂ ಕ್ಷಮಿಸು.", "ಒಬ್ಬರ ತಂದೆ-ತಾಯಿ ಮತ್ತು ವಿಶ್ವಾಸಿಗಳಿಗಾಗಿ.", "ಪ್ರವಾದಿ ನೂಹ್ (ಅ. ಸ.) ಅವರ ದೂ."),
        "dua_shukr_parents" to DuaText("ಹೆತ್ತವರಿಗೆ ಮತ್ತು ನೀತಿವಂತ ಸಂತತಿಗೆ ಕೃತಜ್ಞತೆ", "ನನ್ನ ಒಡೆಯನೇ, ನೀನು ನನಗೆ ಮತ್ತು ನನ್ನ ತಂದೆತಾಯಿಗಳಿಗೆ ನೀಡಿದ ಉಪಕಾರಕ್ಕಾಗಿ ನಾನು ಕೃತಜ್ಞನಾಗಿರಲು ಮತ್ತು ನಿನಗೆ ಹಿತವಾದ ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳನ್ನು ಮಾಡಲು ಮತ್ತು ನನ್ನ ಸಂತತಿಯನ್ನು ನ್ಯಾಯಯುತವಾಗಿಸಲು ನನಗೆ ಅವಕಾಶ ಮಾಡಿಕೊಡು. ನಾನು ನಿನ್ನ ಕಡೆಗೆ ಪಶ್ಚಾತ್ತಾಪ ಪಡುತ್ತೇನೆ ಮತ್ತು ನಾನು ಶರಣಾಗುವವರಲ್ಲಿ ಒಬ್ಬನಾಗಿದ್ದೇನೆ.", "ಕುರಾನ್ ನ ದುಆ ನಲವತ್ತು ವರ್ಷ ವಯಸ್ಸನ್ನು ತಲುಪುತ್ತದೆ.", "ಕೃತಜ್ಞತೆ, ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳು ಮತ್ತು ಒಬ್ಬರ ಮಕ್ಕಳ ನೀತಿ-ಎಲ್ಲವೂ ಒಂದೇ ಯುಗದಲ್ಲಿ."),
        "dua_intimacy" to DuaText("ವೈವಾಹಿಕ ಸಂಬಂಧಗಳ ಮೊದಲು", "ಅಲ್ಲಾಹ್ನ ಹೆಸರಿನಲ್ಲಿ. ಓ ಅಲ್ಲಾಹನೇ, ಸೈತಾನನ್ನು ನಮ್ಮಿಂದ ದೂರವಿಡಿ ಮತ್ತು ಸೈತಾನನ್ನು ನೀನು ನಮಗೆ (ಮಕ್ಕಳಿಗೆ) ನೀಡುವ ದಾನದಿಂದ ದೂರವಿಡಿ.", "ವೈವಾಹಿಕ ಸಂಬಂಧಗಳ ಮೊದಲು.", "ಒಂದು ಮಗುವನ್ನು ನಿರ್ಣಯಿಸಿದರೆ, ಸೈತಾನ್ ಎಂದಿಗೂ ಅದಕ್ಕೆ ಹಾನಿಯನ್ನುಂಟು ಮಾಡುವುದಿಲ್ಲ."),
        "dua_ibrahim_children_protection" to DuaText("ಮನೆ ಮತ್ತು ಮಕ್ಕಳ ರಕ್ಷಣೆ", "ನನ್ನ ಒಡೆಯನೇ, ಈ ನಗರವನ್ನು ಭದ್ರಗೊಳಿಸಿ ಮತ್ತು ನನ್ನನ್ನು ಮತ್ತು ನನ್ನ ಮಕ್ಕಳನ್ನು ವಿಗ್ರಹಗಳ ಪೂಜೆಯಿಂದ ದೂರವಿಡಿ.", "ಪ್ರವಾದಿ ಇಬ್ರಾಹಿಂ (ಅ. ಸ.) ಅವರ ದುಆ-ನಗರ ಮತ್ತು ಅವರ ಮಕ್ಕಳ ಸುರಕ್ಷತೆಗಾಗಿ.", "ತೌಹೀದ್ ಮೇಲೆ ದೃಢವಾಗಿ ಉಳಿಯಲು ಒಂದು ದುಆ."),
        "dua_drinking_milk" to DuaText("ಹಾಲು ಕುಡಿಯುವಾಗ", "ಓ ಅಲ್ಲಾಹನೇ, ನಮಗೆ ಅದನ್ನು ಆಶೀರ್ವದಿಸಿರಿ ಮತ್ತು ನಮಗೆ ಹೆಚ್ಚಿನದನ್ನು ನೀಡಿ.", "ಹಾಲು ಕುಡಿಯುವಾಗ.", "ಹಾಲು ಆಹಾರ ಮತ್ತು ಪಾನೀಯಗಳೆರಡಕ್ಕೂ ಸಾಕಾಗುತ್ತದೆ."),
        "dua_iftar_host" to DuaText("ಇತರರೊಂದಿಗೆ ವೇಗವಾಗಿ ಬೆರೆಯುವಾಗ", "ಉಪವಾಸ ಮಾಡುವ ಜನರು ನಿಮ್ಮೊಂದಿಗೆ ಉಪವಾಸವನ್ನು ಮುರಿಯಲಿ, ನೀತಿವಂತರು ನಿಮ್ಮ ಆಹಾರವನ್ನು ತಿನ್ನಲಿ ಮತ್ತು ದೇವತೆಗಳು ನಿಮಗಾಗಿ ಪ್ರಾರ್ಥಿಸಲಿ.", "ಯಾರೊಬ್ಬರ ಮನೆಯಲ್ಲೂ ಉಪವಾಸವನ್ನು ಮುರಿಯುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರು ಆತಿಥೇಯರಿಗೆ ಸಲ್ಲಿಸುವ ಸಲಾಂ."),
    )
}
